const probes: Scene = {
  id: "probes",
  title: "How the kubelet checks a container",
  width: 848,
  height: 308,
  boxes: [
    { id: "cl", x: 0, y: 0, w: 848, h: 300, label: "Kubernetes cluster", region: "cluster" },
    { id: "w1", x: 10, y: 34, w: 600, h: 256, label: "Node worker-1", icon: "node", region: "node", parent: "cl" },
    { id: "kubelet", x: 20, y: 140, w: 88, h: 48, label: "kubelet", icon: "kubelet", kind: "chip", parent: "w1" },
    { id: "pod", x: 150, y: 60, w: 240, h: 220, label: "Pod web-1", sub: "10.244.1.4", icon: "pod", region: "pod", parent: "w1" },
    { id: "startup", x: 166, y: 92, w: 208, h: 44, label: "startupProbe", sub: "has it finished starting?", kind: "chip", parent: "pod" },
    { id: "live", x: 166, y: 148, w: 208, h: 44, label: "livenessProbe", sub: "is it stuck?", kind: "chip", parent: "pod" },
    { id: "ready", x: 166, y: 204, w: 208, h: 44, label: "readinessProbe", sub: "can it take traffic?", kind: "chip", parent: "pod" },
    { id: "restart", x: 452, y: 148, w: 148, h: 44, label: "Restart container", sub: "RESTARTS + 1", kind: "chip", parent: "w1", tone: "red" },
    { id: "ep", x: 640, y: 210, w: 190, h: 44, label: "EndpointSlice", sub: "Ready Pods only", kind: "chip", parent: "cl" },
  ],
  edges: [
    { id: "k-start", from: "kubelet", to: "startup", label: "period" },
    { id: "k-live", from: "kubelet", to: "live" },
    { id: "k-ready", from: "kubelet", to: "ready" },
    { id: "live-restart", from: "live", to: "restart", label: "3 fails" },
    { id: "ready-ep", from: "ready", to: "ep", label: "in or out" },
  ],
  steps: [
    { title: "The kubelet asks", text: "The kubelet on the Pod's Node runs each probe on a timer (periodSeconds). A probe is an HTTP GET (2xx or 3xx passes), a TCP connection, a gRPC health check, or a command run inside the container (exit code 0 passes).", on: ["kubelet", "pod", "startup", "live", "ready", "k-start", "k-live", "k-ready"], flow: ["k-start", "k-live", "k-ready"], add: ["cl", "w1", "pod", "kubelet", "startup", "live", "ready", "k-start", "k-live", "k-ready"] },
    { title: "Startup comes first", text: "If there is a startup probe, the other two wait until it has passed once. Give a slow app a generous startup probe instead of a long liveness delay.", on: ["kubelet", "startup", "k-start"], flow: ["k-start"] },
    { title: "Readiness: in or out of the Service", text: "When readiness fails failureThreshold times in a row (3 by default), the Pod is marked not Ready and removed from Service endpoints. Nothing restarts. When it passes again, the Pod is added back.", on: ["kubelet", "ready", "ep", "k-ready", "ready-ep"], flow: ["k-ready", "ready-ep"], add: ["ep", "ready-ep"] },
    { title: "Liveness: restart when stuck", text: "When liveness fails 3 times in a row, the kubelet kills the container and starts a new one from the image. The RESTARTS counter goes up; a container that keeps failing ends up in CrashLoopBackOff.", on: ["kubelet", "live", "restart", "k-live", "live-restart"], flow: ["k-live", "live-restart"], add: ["restart", "live-restart"] },
    { title: "Use them together", text: "Readiness can check that the app can serve right now. Liveness should only check the process itself: if it tested the database too, a database outage would restart every Pod for nothing.", on: ["startup", "live", "ready", "restart", "ep", "live-restart", "ready-ep"] },
  ],
};
